-- TPC-H Q06 (sf1), generated by qgen -d -s 1
-- tpch-dbgen commit 32f1c1b92d1664dba542e927d23d86ffa57aa253
-- normalized: dropped 'where rownum <= -1' (no row limit)
select
	sum(l_extendedprice * l_discount) as revenue
from
	lineitem
where
	l_shipdate >= date '1994-01-01'
	and l_shipdate < date '1994-01-01' + interval '1' year
	and l_discount between .06 - 0.01 and .06 + 0.01
	and l_quantity < 24;
